import { afterEach, expect, test } from 'bun:test';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import * as before from './base-types.ts';
import * as generated from './candidate-661d048/packages/model/src/generated/types.ts';
import { renderTypeRegistry } from './candidate-661d048/model/compiler/type.ts';
import { typesV1 } from './candidate-661d048/model/definitions/types-v1.ts';
import { workKindV2Profile } from './candidate-661d048/model/definitions/work-kind-v2.ts';
import { workTypeV2Profile } from './candidate-661d048/model/definitions/work-type-v2.ts';
import { pageRegistry, pageSections } from './candidate-661d048/services/main/src/modules/entity-page/read.ts';
import {
  admittedTypes, assertRegisteredTypeSnapshot, installRegisteredTypes,
  resourceTypeAdmitted, workTypeAdmitted, workSemanticTypeOptions,
  creatableWorkTypeOptions, typeListBody, typeListTag,
} from './candidate-661d048/services/main/src/modules/types/registry.ts';
import { TYPES_READ_COST } from './candidate-661d048/services/main/src/modules/types/contract.ts';
import type { ResolvedTarget } from './candidate-661d048/services/main/src/modules/target/contract.ts';

// Pure compiler/consumer checks over preserved historical captures. No installed
// public read, rendered groups, authority grant or richer fixture is represented.
const resource = 'http://www.w3.org/2000/01/rdf-schema#Resource';
const rv = (name: string) => `https://rezics.com/vocab/${name}`;
const added = ['https://schema.org/Person', 'https://schema.org/Organization',
  'https://schema.org/DefinedTerm', 'https://schema.org/PublicationEvent', rv('SourceDatasetEpisode')];
const original = JSON.parse(readFileSync(new URL('./original-census.json', import.meta.url), 'utf8')) as {
  source: string; target: ResolvedTarget; originalRegistryType: string;
}[];
afterEach(() => installRegisteredTypes([]));

test('exact generated closure preserves all 36 prior entries, defaults, Work metadata and type bounds', () => {
  const registry = generated.typeRegistry as Record<string, typeof generated.typeRegistry[typeof resource]>;
  expect(Object.keys(before.typeRegistry)).toHaveLength(36);
  expect(Object.keys(registry)).toHaveLength(41);
  expect(Object.keys(registry).filter(type => !(type in before.typeRegistry)).sort()).toEqual([...added].sort());
  for (const [type, entry] of Object.entries(before.typeRegistry)) expect(registry[type]).toEqual(entry);
  for (const key of Object.keys(before).filter(key => !['typeRegistry', 'typeRegistryDigest'].includes(key))) {
    expect((generated as Record<string, unknown>)[key]).toEqual((before as Record<string, unknown>)[key]);
  }
  const output = renderTypeRegistry(typesV1, workKindV2Profile, workTypeV2Profile);
  expect(output).toBe(readFileSync(new URL('./candidate-661d048/packages/model/src/generated/types.ts', import.meta.url), 'utf8'));
  expect(createHash('sha256').update(JSON.stringify(registry, null, 2)).digest('hex')).toBe(generated.typeRegistryDigest);
  expect(generated.typeRegistryDigest).toBe('0c6fdfc6b145ffecad6ff52fecc3dd86d016ebb29d4fd2f7eb3d96464faa7e27');
  expect(Object.keys(registry).filter(type => registry[type]!.default)).toEqual(
    Object.keys(before.typeRegistry).filter(type => before.typeRegistry[type as keyof typeof before.typeRegistry].default));
  for (const type of added) {
    expect(registry[type]).toMatchObject({ base: 'resource', default: false, creatable: false,
      creation: 'contributor', interest: null, primaryAction: 'visit', presentation: 'default', priority: 100 });
    for (const key of ['browse', 'frameDimension', 'wikiSegment']) expect(registry[type]).not.toHaveProperty(key);
    expect(Object.keys(registry[type]!.labels)).toEqual([...generated.typeLocales]);
    for (const forms of Object.values(registry[type]!.labels)) {
      expect(forms.one.length).toBeGreaterThan(0); expect(forms.other.length).toBeGreaterThan(0);
    }
    expect(resourceTypeAdmitted(type)).toBe(true); expect(workTypeAdmitted(type)).toBe(false);
    expect(workSemanticTypeOptions).not.toContain(type); expect(creatableWorkTypeOptions).not.toContain(type);
  }
  expect(JSON.parse(typeListBody).types).toHaveLength(41);
  expect(Buffer.byteLength(typeListBody)).toBeLessThanOrEqual(TYPES_READ_COST.maxBytes);
  expect(JSON.parse(typeListBody).types.length).toBeLessThanOrEqual(TYPES_READ_COST.maxTypes);
});

test('the original 27 captured targets select all 19 corrected descriptive entries and retain eight Character controls', () => {
  const census: Record<string, number> = {};
  const mounted = new Set(['statements', 'relations', 'discussion', 'credits', 'releases', 'contents', 'ratings', 'reviews']
    .map(section => `/v1/resources/:resource/${section}`));
  let corrected = 0, controls = 0;
  expect(original).toHaveLength(27);
  for (const row of original) {
    const preserved = structuredClone(row.target);
    const descriptive = row.target.types.filter(type => type !== resource);
    expect(descriptive).toHaveLength(1);
    const type = descriptive[0]!;
    census[type] = (census[type] ?? 0) + 1;
    expect(pageRegistry(row.target)).toEqual(generated.typeRegistry[type as keyof typeof generated.typeRegistry]);
    expect(pageRegistry(row.target).default).toBe(false);
    expect(pageSections(row.target, mounted)).toEqual(['statements', 'relations', 'discussion'].map(id => ({
      id, href: `/v1/resources/${row.target.resource.slice(-36)}/${id}`, actions: [],
    })));
    expect(row.target).toEqual(preserved);
    if (type === rv('Character')) { expect(row.originalRegistryType).toBe(type); controls++; }
    else { expect(row.originalRegistryType).toBe(resource); corrected++; }
  }
  expect(census).toEqual({ [rv('Character')]: 8, 'https://schema.org/Person': 5,
    'https://schema.org/Organization': 4, 'https://schema.org/DefinedTerm': 3,
    'https://schema.org/PublicationEvent': 4, [rv('SourceDatasetEpisode')]: 3 });
  expect(corrected).toBe(19); expect(controls).toBe(8);
});

test('mixed and unknown types retain exact IRI matching, base separation and deterministic existing tie rules', () => {
  for (const type of added) {
    for (const types of [[type, resource, 'urn:unknown:type'], ['urn:unknown:type', resource, type], [type, type]]) {
      expect(pageRegistry({ base: 'resource', types }).type).toBe(type);
    }
    expect(pageRegistry({ base: 'work', types: [type] }).type).toBe('https://schema.org/CreativeWork');
    expect(pageRegistry({ base: 'release', types: [type] }).type).toBe(rv('Record'));
  }
  for (const types of [[], ['Person'], ['urn:unknown:type'], ['http://schema.org/Person'],
    ['https://schema.org/Person#unregistered'], ['https://schema.org/MusicComposition'],
    ['https://schema.org/TVEpisode'], ['http://www.w3.org/ns/dcat#Dataset']]) {
    expect(pageRegistry({ base: 'resource', types }).type).toBe(resource);
  }
  for (const types of [['https://schema.org/Person', 'https://schema.org/Organization'],
    ['https://schema.org/Organization', 'https://schema.org/Person']]) {
    expect(pageRegistry({ base: 'resource', types }).type).toBe('https://schema.org/Organization');
  }
  expect(pageRegistry({ base: 'resource', types: ['https://schema.org/Person', rv('Character')] }).type).toBe(rv('Character'));
  expect(pageRegistry({ base: 'resource', types: ['https://schema.org/Person', rv('Agent')] }).type).toBe(rv('Agent'));
  expect(pageRegistry({ base: 'release', types: ['https://schema.org/PublicationEvent', rv('Release')] }).type).toBe(rv('Release'));
  expect(pageRegistry({ base: 'work', types: ['https://schema.org/Person', 'https://schema.org/MusicRecording'] }))
    .toEqual(before.typeRegistry['https://schema.org/MusicRecording']);
});

test('compiled descriptive metadata wins over active and retired older rows without widening Work admission or erasing distinct retired types', () => {
  const tag = typeListTag;
  for (const lifecycle of ['active', 'retired'] as const) {
    const rows = added.map(type => ({ definition: { ...pageRegistry({ base: 'resource', types: [type] }),
      base: 'work' as const, creatable: true, priority: 0 }, lifecycle, revision: '2' }));
    assertRegisteredTypeSnapshot(rows); installRegisteredTypes(rows);
    expect(typeListTag).toBe(tag);
    for (const type of added) {
      expect(admittedTypes.filter(entry => entry.type === type)).toEqual([generated.typeRegistry[type as keyof typeof generated.typeRegistry]]);
      expect(resourceTypeAdmitted(type)).toBe(true); expect(workTypeAdmitted(type)).toBe(false);
      expect(workSemanticTypeOptions).not.toContain(type); expect(creatableWorkTypeOptions).not.toContain(type);
    }
  }
  const type = 'urn:independent:older-descriptive-type';
  const definition = { ...pageRegistry({ base: 'resource', types: ['https://schema.org/Person'] }), type };
  installRegisteredTypes([{ definition, lifecycle: 'retired', revision: '2' }]);
  expect(pageRegistry({ base: 'resource', types: [type] })).toEqual(definition);
  expect(resourceTypeAdmitted(type)).toBe(false);
  expect(workTypeAdmitted(type)).toBe(false);
});
